const api = 'https://www.trxs666.com'

function getApiUrl(path, data = {}) {
  data = Object.entries(data).map(v => v.join('=')).join('&')
  let option = {
    method: "GET",
    headers: {
      'authorization': `Bearer ${this.source.getVariable() || ''}`,
    }
  }
  let url = api + path + '?' + data + ',' + JSON.stringify(option)
  return url
}

function requestApiUrl(path, data = {}) {
  let url = getApiUrl.call(this, path, data)
  try {
    let res = JSON.parse(this.java.ajax(url))
    if (res.msg && res.msg != 'success') {
      this.java.longToast(`\n操作失败，code${res.code}：\n${res.msg}`)
    }
    if (res.data) {
      return res.data
    }
  } catch (e) {
    this.java.log(`请求共享接口${path}异常：` + e.message)
  }
  return null
}

function getComments(content, bid, cid) {
  // 主函数
  let { source, java, cache } = this
  let isPC = source.get("段评") == '1'
  let isCC = source.get("章评") == '1'
  content = String(content)
  if (!bid || !cid || (!isPC && !isCC)) {
    return content
  }
  try {
    if (isPC) {
      let separator = "\n"
      if (/<p>/.test(content)) {
        content = content.replace(/^<p>/, "").replace(/\n$/, "")
        separator = "<p>"
      } else {
        content = content.replace(/\r/g, "").replace(/\n$/, "")
      }
      let spcontent = content.split(separator)
      let url = `https://m.qidian.com/majax/chapterReview/reviewSummary?bookId=${bid}&chapterId=${cid}&${getCsrfToken(this)}`
      let comments = java.get(url, {}).body()
      let list = JSON.parse(comments).data.list
      let isImageOnly = value => /^\s*<img.*>\s*$/.test(value)
      let paragraphPositions = []
      let paragraphCount = 0
      for (let i = 0; i < spcontent.length; i++) {
        if (isImageOnly(spcontent[i]) || spcontent[i] == '') {
          continue
        }
        paragraphCount += 1
        paragraphPositions[paragraphCount] = i
      }
      list.forEach(x => {
        let pindex = paragraphPositions[x.paragraphId]
        if (pindex === undefined) return
        spcontent[pindex] += `<img src="data:image/svg+xml;base64,,{"style":"TEXT","type":"qdzw","click":"createSvg(${bid},${cid},${x.paragraphId},${x.textCount},${Packages.java.lang.System.nanoTime()})","js":"createSvg(${bid},${cid},${x.paragraphId},${x.textCount},${Packages.java.lang.System.nanoTime()})"}">`
        let mname = `qdreader-${bid}-${cid}-${x.paragraphId}`
        cache.putMemory(mname, "1")
      })
      let x = list[0]
      if (x.paragraphId == -1 && x.textCount > 0) {
        let svg = `<img src="data:image/svg+xml;base64,,{"style":"TEXT","type":"qdzw","click":"createSvg(${bid},${cid},-1,${x.textCount},${Packages.java.lang.System.nanoTime()})","js":"createSvg(${bid},${cid},-1,${x.textCount},${Packages.java.lang.System.nanoTime()})"}">`
        // spcontent.unshift(svg)
        let mname = `qdreader-${bid}-${cid}-${x.paragraphId}`
        cache.putMemory(mname, "1")
        svg = createSvg0.call(this, bid, cid, -1, x.textCount, Packages.java.lang.System.nanoTime())
        cache.putMemory(cid, svg)
        cache.deleteMemory(mname)
      }
      content = spcontent.join("\n")
    }
    if (isCC) {
      let data = requestApiUrl.call(this, '/novel/comment/chapter_list', { bid, cid })
      if (!data) return content
      let count = data.total || 0
      if (!count) return content
      if (count > 999) count = 999
      let pid = -2
      content += `\n<img src="data:image/svg+xml;base64,,{"style":"FULL","type":"qdzw","click":"createSvg2(${bid},${cid},${pid},${count},${Packages.java.lang.System.nanoTime()})","js":"createSvg2(${bid},${cid},${pid},${count},${Packages.java.lang.System.nanoTime()})"}">`
      let cacheKey = `qdreader-${bid}-${cid}-${pid}`
      cache.putMemory(cacheKey, '1')
    }
    return content
  } catch (e) {
    java.log(e)
    return content
  }
}

function checkEnv() {
  try {
    new Packages.io.legato.kazusa.utils.TimeoutCancellationException('')
    return true
  } catch (e) { }
  try {
    return typeof this.source.loginUi === 'function' ? false : true
  } catch {
    return false
  }
}

function createSvg0(bid, cid, pid, count) {
  let svg = createSvg.call(this, bid, cid, pid, count)
  return `${svg},{"style":"TEXT","type":"qdzw","click":"createSvg(${bid},${cid},${pid},${count},${Packages.java.lang.System.nanoTime()})"}`
}

function createSvg(bid, cid, pid, count) {
  let { java, cache, source } = this
  let mname = `qdreader-${bid}-${cid}-${pid}`
  let load = cache.getFromMemory(mname)
  if (load == "1") {
  } else {
    let token = String(source.getVariable())
    if (token == '') {
      java.longToast('请先于【源变量】处填写共享Token后使用段评功能')
    } else {
      let type = source.get("段评APP数据源") == '1' ? 'app' : 'web'
      if (checkEnv.call(this)) {
        java.showBrowser(
          `${api}/novel/comment/page?bid=${bid}&cid=${cid}&pid=${pid}&type=${type}&token=${token}`,
          null,
          null,
          JSON.stringify({
            state: 6, // 半展开
            // peekHeight: 450, // 设置折叠状态下的高度（像素）
            isHideable: true, // 是否可以通过下滑关闭弹窗
            setHalfExpandedRatio: 0.8, // 设置半展开状态的比例（0.0-1.0），相对于父容器的高度
            heightPercentage: 0.8, // 弹窗高度占屏幕高度的百分比（0.0-1.0）
            expandedCornersRadius: 20, // 展开状态的圆角半径
            dismissOnTouchOutside: true, // 点击外部是否关闭弹窗
            widthPercentage: 1.0, // 弹窗宽度占屏幕宽度的百分比（0.0-1.0）
            maxWidth: -1, // 设置弹窗的最大宽度（像素）
            isGestureInsetBottomIgnored: true, // 是否忽略系统手势区域（如下方的导航条）
          }))
      } else {
        java.startBrowser(`${api}/novel/comment/page?bid=${bid}&cid=${cid}&pid=${pid}&type=${type}&token=${token}`, '段评')
      }
    }
  }
  let color = String(this.source.get('paragraph_comment_svg_color')) || '#FF0000'
  let displayText = count > 999 ? 999 : count
  let svg = `<svg width="1000" height="800" xmlns="http://www.w3.org/2000/svg">
  <rect x="150" y="150" width="665" height="525" rx="175" ry="175" fill="none" stroke="${color}" stroke-width="17.5" />
  <text x="480" y="535" font-family="Arial, sans-serif" text-anchor="middle" dominant-baseline="middle"
    font-size="297.5" fill="${color}">${displayText}</text>
</svg>`
  let encodedSvg = this.java.base64Encode(svg)
  return `data:image/svg+xml;base64,${encodedSvg}`
}

function createSvg2(bid, cid, pid, count) {
  let { java, cache, source } = this
  let cacheKey = `qdreader-${bid}-${cid}-${pid}`
  let load = this.cache.getFromMemory(cacheKey)
  if (load == '1') {
  } else {
    let token = String(this.source.getVariable())
    if (checkEnv.call(this)) {
      this.java.showBrowser(
        `${api}/novel/comment/page?bid=${bid}&cid=${cid}&pid=&type=app&token=${token}`,
