          heightPercentage: 0.8, // 弹窗高度占屏幕高度的百分比（0.0-1.0）
          expandedCornersRadius: 20, // 展开状态的圆角半径
          dismissOnTouchOutside: true, // 点击外部是否关闭弹窗
          widthPercentage: 1.0, // 弹窗宽度占屏幕宽度的百分比（0.0-1.0）
          maxWidth: -1, // 设置弹窗的最大宽度（像素）
          isGestureInsetBottomIgnored: true, // 是否忽略系统手势区域（如下方的导航条）
        }))
    } else {
      this.java.startBrowser(`${api}/novel/comment/page?bid=${bid}&cid=${cid}&pid=&type=app&token=${token}`, '章评')
    }
  }
  let displayText = count > 999 ? 999 : count
  let svg = `<svg width="1000" height="120" xmlns="http://www.w3.org/2000/svg">
    <rect width="1000" height="120" fill="#A9A9A9" rx="15" />
    <text x="100" y="75" font-family="Arial" font-size="48" fill="#000000" text-anchor="start">本章讨论</text>
    <g transform="translate(850, 60)">
      <rect x="-40" y="-30" width="80" height="60" rx="20" ry="20" stroke="#000000" stroke-width="2" fill="none" />
      <text x="0" y="12" font-family="Arial" font-size="36" fill="#000000" text-anchor="middle"
