function login() { }

function _login() {
  let token = String(source.getVariable())
  if (!token) {
    java.longToast('\n❌请先于【源变量】处填写共享Token')
    return
  }
  java.startBrowser(`${api}/console/login?token=${token}`, '登录页')
}

function queryToken() {
  let token = String(source.getVariable())
  if (token.length <= 60) {
    java.toast('请先于【源变量】处填写共享Token')
  } else {
    let info = requestApiUrl('/user/test')
    if (!info) return
    java.longToast(`\n✅查询成功\n${info.msg}`)
  }
}

function registerByInvite() {
  let code = String(result['邀请码'])
  if (code == '') {
    return java.longToast('请输入邀请码')
  }
  let info = requestApiUrl('/user/invite', { id: java.androidId(), code: code }, this)
  if (!info) return
  let token = info.token
  source.setVariable(token)
  java.longToast(`\n✅邀请码注册成功\n用户：${info.id}\n日下载剩余：${info.left}\n创建时间：${info.createTime}\n到期时间：${info.ddlTime}`)
  source.putLoginInfo(JSON.stringify(result))
}

function showDb() {
  let data = requestApiUrl('/system/dbinfo')
  if (!data) return
  java.longToast(`\n✅${data.msg}`)
}

function showUserInfo() {
  let data = requestApiUrl('/console/info')
  if (!data) return
  java.longToast(`\n✅查询成功\n${data.msg}`)
}

function setType(type) {
  source.put('type', type)
  java.longToast(`\n✅发现页模式已切换为：${type}\n刷新发现页后生效`)
}

function setOrder(order, desc) {
  source.put('order', order)
  java.longToast(`\n✅搜索、发现页排序已切换为：${desc}\n实时生效`)
}

function setGender(gender) {
  source.put('gender', gender)
  java.longToast(`\n✅发现页小说频道已切换为：${gender ? '男频' : '女频'}\n刷新发现页后生效`)
}

function switchSetting(key, tip) {
  let old = source.get(key) || '0'
  let now = old == '1' ? '0' : '1'
  source.put(key, now)
  java.longToast(`\n✅${key}已${now == '1' ? '开启' : '关闭'}${tip ? `\n${tip}` : ''}`)
}

function downloadNovel() {
  let novelId = +result['书籍ID']
  if (!novelId) {
    return java.toast('请输入有效书籍ID')
  }
  let data = requestApiUrl('/novel/download', { novelId })
  if (!data) return
  java.longToast(`\n✅${data.msg}`)
  source.putLoginInfo(JSON.stringify(result))
}

function change_paragraph_comment_svg_color() {
  let color = String(result['段评气泡颜色'])
  if (!/^#([0-9a-fA-F]{6})$/.test(color)) {
    return java.longToast('\n❌请输入有效的颜色值，如：#FF0000')
  }
  source.put('paragraph_comment_svg_color', color)
  source.putLoginInfo(JSON.stringify(result))
  java.longToast(`\n✅段评气泡颜色已设置为：${color}`)
}

function buy(all) {
  let novelId = +String(result['书籍ID'])
  if (!novelId) {
    return java.longToast('\n❌请输入有效书籍ID')
  }
  let withChapterCard = source.get('章节卡') == '1'
  let data
  if (all) {
    data = requestApiUrl('/novel/buy_novel', { novelId, withChapterCard })
  } else {
    let num = +String(result['购买数量'])
    if (!num || num <= 0) {
      num = 5
    }
    data = requestApiUrl('/novel/buy_chapter', { novelId, num, withChapterCard })
